  // Separate state for home buying calculator (added here so it's defined before render)
  const [homeCalcState, setHomeCalcState] = useState('QLD')
  const [homeCalcFirstHome, setHomeCalcFirstHome] = useState(true)
  const [homeCalcNewBuild, setHomeCalcNewBuild] = useState(false)
  const [homeBuyingPrice, setHomeBuyingPrice] = useState('')

  // ==================== WEEKLY PLAN GENERATOR ====================
  const generateWeeklyPlan = async (milestoneId: number) => {
    const milestone = roadmapMilestones.find(m => m.id === milestoneId)
    if (!milestone) return
    const isDebtMilestone = /\bkill bad\b|\bpay.*off.*debt\b|\bdebt.*payoff\b|\bcredit card\b|\bbnpl\b|\bpersonal loan\b/i.test(milestone.name)
    setGeneratingPlanFor(milestoneId)
    try {
      const response = await fetch('/api/budget-coach', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          mode: 'question',
          question: `You are Aureus, an AI financial coach built into a budgeting app called Aureus. The user is already using Aureus to track their budget, income, expenses, debts, and goals — so NEVER suggest they download a budgeting app, spreadsheet, or any other tracking tool. They already have one.  Important financial context for Australian users: - The $2,000 Starter Emergency Fund (Baby Step 1) is a buffer for UNEXPECTED emergencies like car breakdowns, medical bills, vet bills, or appliance failures — it is NOT meant to cover a month of living expenses. Do not describe it that way. - Baby Step 3 (3-6 months of expenses) is the full emergency fund — different goal.  Create a 7-step action plan for this goal: "${milestone.name}"${milestone.targetAmount ? ` (target: $${milestone.targetAmount})` : ''}${milestone.notes ? `. Context: ${milestone.notes}` : ''}. Rules: - Output ONLY the 7 steps, nothing else. No intro sentence, no summary, no preamble. - Format each line as: Step 1: [action] - Each action must be specific, concrete, and doable — no fixed day requirement, user does them at their own pace - One sentence per step - Never suggest downloading another app or creating a spreadsheet — the user is already in Aureus - MILESTONE TYPE: This is ${isDebtMilestone ? 'a DEBT PAYOFF milestone. Step 5 MUST be EXACTLY this word for word: "Add this debt to the Debts section in Aureus with the balance, interest rate, and minimum payment so it tracks your payoff progress automatically." Do NOT change a single word.' : 'a SAVINGS GOAL milestone — NOT a debt. Do NOT use the word "debt" anywhere in your plan. Step 5 MUST be EXACTLY this word for word: "Add this goal to your Aureus savings goals with your target amount and a weekly payment amount, then enable it on the calendar for visual tracking and reminders." Do NOT change a single word.'} - Start directly with "Step 1:"${getPersonalityCoachingContext()}`,
          financialData: { income: incomeStreams, expenses, debts, goals, assets, liabilities },
          memory: budgetMemory,
          countryConfig: currentCountryConfig
        })
      })
      const data = await response.json()
      const rawText: string = data.message || data.advice || data.raw || ''
      const lines = rawText.split('\n').map((l: string) => l.trim()).filter((l: string) => l.length > 0)

      // Strip markdown bold/italic from a string
      const stripMd = (s: string) => s
        .replace(/\*\*([^*]+)\*\*/g, '$1')  // **bold**
        .replace(/\*([^*]+)\*/g, '$1')       // *italic*
        .replace(/^#+\s*/, '')               // headings
        .trim()

      // Filter to only lines that start with Day N / Step N / number - skip intro prose
      const dayLines = lines.filter((l: string) => /^(day\s*\d+|step\s*\d+|\d+[).\-:])/i.test(l))
      const sourceLines = dayLines.length >= 5 ? dayLines : lines.filter((l: string) => {
        // also skip obvious intro/outro lines
        const stripped = stripMd(l).toLowerCase()
        return !stripped.startsWith("here's") && !stripped.startsWith("here is") &&
               !stripped.startsWith("below") && !stripped.startsWith("sure") &&
               !stripped.startsWith("great") && !stripped.startsWith("absolutely") &&
               !stripped.startsWith("of course") && l.length > 20
      })

      const goalDay5 = 'Add this goal to your Aureus savings goals with your target amount and a weekly payment amount, then enable it on the calendar for visual tracking and reminders.'
      const debtDay5 = 'Add this debt to the Debts section in Aureus with the balance, interest rate, and minimum payment so it tracks your payoff progress automatically.'

      const parsed = sourceLines.slice(0, 7).map((l: string, i: number) => {
        let text = stripMd(l.replace(/^(day\s*\d+[:.\-]?\s*|step\s*\d+[:.\-]?\s*|\d+[).\-]\s*)/i, '').trim())
        // Safety net: if AI hallucinated wrong Day 5, override it
        if (i === 4) {
          if (!isDebtMilestone && /add this debt|debts section/i.test(text)) text = goalDay5
          if (isDebtMilestone && /add this goal|savings goals/i.test(text)) text = debtDay5
        }
        return { id: Date.now() + i, text, done: false }
      }).filter((s: any) => s.text.length > 10)
      setRoadmapMilestones(prev => prev.map(m =>
        m.id === milestoneId ? { ...m, weeklyPlan: parsed, planGeneratedAt: new Date().toISOString() } : m
      ))
      setExpandedMilestone(milestoneId)
    } catch { alert('Could not generate plan — please try again.') }
    setGeneratingPlanFor(null)
  }

  // ══════════════════════════════════════════════════════════════
  // COACHING IMPROVEMENT #4 & #8 — AMBIENT CHAT (Ask Aureus about THIS)
  // ══════════════════════════════════════════════════════════════
  const askAureusAbout = (context: string) => {
    setChatContext(context)
    setActiveTab('chat')
      }

  const togglePlanStep = (milestoneId: number, stepId: number) => {
    setRoadmapMilestones(prev => prev.map(m =>
      m.id === milestoneId
        ? { ...m, weeklyPlan: m.weeklyPlan?.map((s: any) => s.id === stepId ? { ...s, done: !s.done } : s) }
        : m
    ))
  }

  const addToRoadmapQuick = (name: string, icon: string, targetAmount: string, notes: string) => {
    if (roadmapMilestones.some(m => m.name.toLowerCase() === name.toLowerCase())) {
      alert(`"${name}" is already on your roadmap!`)
      return
    }
    setRoadmapMilestones(prev => [...prev, {
      id: Date.now(), name, icon, targetAmount, currentAmount: 0,
      targetDate: '', notes, category: 'savings', completed: false,
      createdAt: new Date().toISOString(), weeklyPlan: null
    }])
    setCelebrationWin(`"${name}" added to your roadmap! 🗺️`)
    setTimeout(() => setCelebrationWin(null), 3000)
  }

  // ── Web search trigger detection ──
  const shouldUseWebSearch = (msg: string): boolean => {
    const lower = msg.toLowerCase()
    return [
      /\b(current|today'?s?|latest|now|2025|2026)\b.*\b(rate|price|cost|value|yield)/,
      /\b(interest rate|cash rate|rba|mortgage rate|home loan rate|savings rate|term deposit|hysa)\b/,
      /\b(asx|share price|stock price|etf|dividend|market)\b/,
      /\b(median (house|property|unit) price|rental yield|suburb|corelogic|domain)\b/,
      /\b(concessional cap|super limit|contribution limit|tax bracket|medicare levy|hecs)\b/,
      /\b(passive income idea|best savings account|high interest|best rate)\b/,
      /\b(grocery|supermarket|woolworths|coles|aldi|price of|on special|catalog|meal plan|recipe cost)\b/,
      /\b(what is the current|what are current|what'?s? the (current|latest)|how much does .* cost (now|today))\b/,
    ].some(r => r.test(lower))
  }

  // ── Sinking funds helpers ──
  const addSinkingFund = () => {
    if (!newSinkingFund.name || !newSinkingFund.targetAmount) return
    const target = parseFloat(newSinkingFund.targetAmount)
    const targetDate = newSinkingFund.targetDate
    let weeklyAmt = parseFloat(newSinkingFund.weeklyAmount || '0')
    // Auto-calc weekly if date given and no manual amount
    if (!weeklyAmt && targetDate) {
      const weeksLeft = Math.max(1, Math.ceil((new Date(targetDate).getTime() - Date.now()) / (7 * 86400000)))
      weeklyAmt = parseFloat((target / weeksLeft).toFixed(2))
    }
    setSinkingFunds(prev => [...prev, {
      ...newSinkingFund, id: Date.now(),
      weeklyAmount: weeklyAmt.toString(),
      savedAmount: '0',
      createdAt: new Date().toISOString()
    }])
    setNewSinkingFund({ name: '', targetAmount: '', targetDate: '', weeklyAmount: '', category: 'celebration', notes: '' })
  }
  const deleteSinkingFund = (id: number) => setSinkingFunds(prev => prev.filter(f => f.id !== id))
  const addToSinkingFund = (id: number, amount: number) => setSinkingFunds(prev => prev.map(f => f.id === id ? { ...f, savedAmount: (parseFloat(f.savedAmount || '0') + amount).toFixed(2) } : f))

  // ── Trigger full-screen celebration ──
  const triggerCelebration = (title: string, message: string, emoji: string, type: 'win' | 'debt_free' | 'goal_hit' | 'baby_step' | 'streak' = 'win') => {
    setCelebrationData({ title, message, emoji, type })
    setCelebrationWin(message)
    setTimeout(() => setCelebrationWin(null), 5000)
  }

  // ── COMPLIANCE OUTPUT FILTER (Part A decision test) ──
  // Checks AI responses for advice-like content before displaying
  const checkComplianceFilter = (text: string): { safe: boolean; rewrite?: string } => {
    // Don't flag responses already declining properly
    const isAlreadyDeclining = (
      text.includes("not licensed") ||
      text.includes("isn't licensed") ||
      text.includes("Aureus isn't") ||
      text.includes("can't give financial advice") ||
      text.includes("financial advice and Aureus") ||
      (text.includes("speak with a licensed") && !text.includes("should")) ||
      text.includes("moneysmart.gov.au") ||
      text.includes("yoursuper.gov.au")
    )
    if (isAlreadyDeclining) return { safe: true }

    // Patterns that indicate actual product advice slipped through
    const advicePatterns = [
      // Evaluating a named fund/product
      /\b(australiansuper|aust(?:ralian)? super|vanguard|betashares|raiz|spaceship|commsec|ubank|ing direct|macquarie|hostplus|sunsuper|rest super|cbus|hesta)\b.{0,100}(well.?regarded|competitive|strong (returns?|performance)|solid|good (choice|option|fund)|known for|one of the (best|top|largest))/i,
      // "My suggestion" or "I suggest/recommend" about a product
      /\bmy (suggestion|recommendation|advice)\b.{0,60}(super|fund|etf|shares|loan|card|invest)/i,
      /\b(i'?d |you should |i suggest |i recommend ).{0,80}(super|fund|etf|shares|loan|mortgage|credit card|switch|move|invest)/i,
      // Tax advice
      /\byou (can|could|should) claim.{0,40}(deduction|as a tax|on your tax)/i,
      /\breduce (your )?tax\b.{0,60}(by|through|structur|if you|consider)/i,
      // Credit advice
      /\b(should|i'?d) (refinance|consolidate|get a|pay off the card|apply for).{0,40}(loan|mortgage|card|credit)/i,
    ]

    const hasActualAdvice = advicePatterns.some(p => p.test(text))
    if (hasActualAdvice) {
      return {
        safe: false,
        rewrite: `I need to step back — I'm not licensed to give financial product recommendations, and my response was crossing that line.\n\nWhat I can do: show you your own tracked numbers, explain how things work, and point you to the right tools.\n\n**For comparing super funds:** Use the ATO's [YourSuper tool](https://yoursuper.gov.au) — it shows fees and net returns side by side across all funds.\n\n**For product decisions:** A licensed financial adviser can assess your specific situation.\n\nWant me to show you what's tracked in your Aureus data instead?`
      }
    }
    return { safe: true }
  }
  const [mealPlanError, setMealPlanError] = useState<string | null>(null)
  // ── Fetch recipe for a specific meal ──
  const [recipeError, setRecipeError] = useState<string | null>(null)
  const fetchRecipe = async (mealName: string) => {
    const cleanName = mealName.replace(/~\$[\d.]+/g, '').replace(/\(.*?\)/g, '').replace(/\s+/g, ' ').trim()
    if (!cleanName) return
    setFetchingRecipe(cleanName)
    setRecipeError(null)
    try {
      const response = await fetch('/api/recipe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          meal: cleanName,
          serves: currentMealPlan?.prefs?.people || 4,
          dislikes: currentMealPlan?.prefs?.dislikes || '',
          dietaryNeeds: currentMealPlan?.prefs?.dietaryNeeds || '',
          budget: currentMealPlan?.weeklyBudget || ''
        })
      })
      const data = await response.json()
      if (!response.ok) throw new Error(data?.error || `Server error ${response.status}`)
      if (!data.text) throw new Error('No recipe returned — please try again.')
      setRecipeModal({ meal: cleanName, text: data.text })
    } catch (e: any) {
      console.error('Recipe fetch error:', e)
      setRecipeError(e?.message || 'Could not load recipe. Check that /api/recipe/route.ts is deployed.')
    }
    setFetchingRecipe(null)
  }

  // ── Build snapshot of all user data ──
  const buildSnapshot = () => ({
    aureus_token: localStorage.getItem('aureus_user_token') || '',
    userName, whyStatement, budgetMemory, userCountry,
    incomeStreams, expenses, debts, goals, assets, liabilities,
    sinkingFunds, categoryBudgets, actualSpend,
    superData, mealPlanPrefs, mealPlanHistory,
    missionComplete, missionPhase, missionStep,
    missionP2Proposals, missionP2Confirmed, missionP2Step,
    onboardingComplete, houseStatus, fireGoal, moneyPersonality,
    wins, streak, lastCheckIn,
    coreValues, identityStatement, mustStatement, futureVision,
    identityStatements, proactiveInsights, insightsGeneratedAt,
    businessProfile, businessRevenue, businessExpenses, businessGoals,
    notificationEmail, emailNotifEnabled, emailNotifFrequency,
    monthlyMealPlanOptIn, accountabilityEmail, accountabilityName,
    mortgageAccel, investmentProperties, lastMirrorMonth,
    roadmapMilestones,
    latteItems, dailyCheckInLog, moneyDateLog, annualReviews,
    coachNextAction, dismissedTriggers, lastAppOpen,
    personalityAnswers, deepWhyAnswers, deepWhyComplete,
    saved_at: new Date().toISOString()
  })

  // ── Save snapshot to Supabase ──
  const saveToCloud = async (user?: any) => {
    const u = user || authUser
    if (!u) return
    try {
      setSyncStatus('saving')
      const sb = await getSb()
      const { error } = await sb.from('user_data').upsert({
        user_id: u.id,
        email: u.email,
        aureus_token: localStorage.getItem('aureus_user_token') || '',
        snapshot: buildSnapshot()
      }, { onConflict: 'user_id' })
      setSyncStatus(error ? 'error' : 'saved')
    } catch { setSyncStatus('error') }
  }

  // ── Load snapshot from Supabase ──
  const loadFromCloud = async (user: any): Promise<boolean> => {
    try {
      const sb = await getSb()
      const { data } = await sb.from('user_data').select('snapshot, aureus_token').eq('user_id', user.id).single()
      if (!data?.snapshot) return false
      const s = data.snapshot
      // Clear any previous user's local data before loading this user's cloud data
      localStorage.removeItem('aureus_data')
      localStorage.removeItem('aureus_business')
      if (data.aureus_token) localStorage.setItem('aureus_user_token', data.aureus_token)
      if (s.userName) setUserName(s.userName)
      if (s.whyStatement) setWhyStatement(s.whyStatement)
      if (s.budgetMemory) setBudgetMemory(s.budgetMemory)
      if (s.userCountry) setUserCountry(s.userCountry)
      if (s.incomeStreams?.length) setIncomeStreams(s.incomeStreams)
      if (s.expenses?.length) setExpenses(s.expenses)
      if (s.debts?.length) setDebts(s.debts)
      if (s.goals?.length) setGoals(s.goals)
      if (s.assets?.length) setAssets(s.assets)
      if (s.liabilities?.length) setLiabilities(s.liabilities)
      if (s.sinkingFunds?.length) setSinkingFunds(s.sinkingFunds)
      if (s.categoryBudgets) setCategoryBudgets(s.categoryBudgets)
      if (s.actualSpend) setActualSpend(s.actualSpend)
      if (s.superData) setSuperData(s.superData)
      if (s.mealPlanPrefs) setMealPlanPrefs(s.mealPlanPrefs)
      if (s.mealPlanHistory?.length) setMealPlanHistory(s.mealPlanHistory)
      if (s.missionComplete) { setMissionComplete(true); setOnboardingComplete(true) }
      if (s.missionPhase) setMissionPhase(s.missionPhase)
      if (s.missionStep !== undefined) setMissionStep(s.missionStep)
      if (s.missionP2Proposals?.length) setMissionP2Proposals(s.missionP2Proposals)
      if (s.missionP2Confirmed?.length) setMissionP2Confirmed(s.missionP2Confirmed)
      if (s.wins?.length) setWins(s.wins)
      if (s.streak) setStreak(s.streak)
      if (s.coreValues?.length) setCoreValues(s.coreValues)
      if (s.identityStatement) setIdentityStatement(s.identityStatement)
      if (s.mustStatement) setMustStatement(s.mustStatement)
      if (s.futureVision) setFutureVision(s.futureVision)
      if (s.identityStatements?.length) setIdentityStatements(s.identityStatements)
      if (s.businessProfile) setBusinessProfile(s.businessProfile)
      if (s.businessRevenue?.length) setBusinessRevenue(s.businessRevenue)
      if (s.businessExpenses?.length) setBusinessExpenses(s.businessExpenses)
      if (s.businessGoals?.length) setBusinessGoals(s.businessGoals)
      if (s.notificationEmail) setNotificationEmail(s.notificationEmail)
      if (s.emailNotifFrequency) setEmailNotifFrequency(s.emailNotifFrequency)
      if (s.monthlyMealPlanOptIn) setMonthlyMealPlanOptIn(s.monthlyMealPlanOptIn)
      if (s.accountabilityEmail) setAccountabilityEmail(s.accountabilityEmail)
      if (s.accountabilityName) setAccountabilityName(s.accountabilityName)
      if (s.mortgageAccel) setMortgageAccel(s.mortgageAccel)
      if (s.investmentProperties?.length) setInvestmentProperties(s.investmentProperties)
      if (s.roadmapMilestones?.length) setRoadmapMilestones(s.roadmapMilestones)
      if (s.latteItems?.length) setLatteItems(s.latteItems)
      if (s.moneyDateLog?.length) setMoneyDateLog(s.moneyDateLog)
      if (s.coachNextAction) setCoachNextAction(s.coachNextAction)
      if (s.houseStatus) setHouseStatus(s.houseStatus)
      if (s.moneyPersonality) setMoneyPersonality(s.moneyPersonality)
      if (s.personalityAnswers) setPersonalityAnswers(s.personalityAnswers)
      return true
    } catch { return false }
  }

  // ── Forgot password ──
  const handleForgotPassword = async () => {
    if (!authEmail.trim()) { setAuthError('Please enter your email address.'); return }
    setAuthLoading(true); setAuthError('')
    try {
      const sb = await getSb()
      const { error } = await sb.auth.resetPasswordForEmail(authEmail.trim(), {
        redirectTo: `${window.location.origin}/dashboard?reset=true`
      })
      if (error) throw error
      setAuthError('✅ Reset email sent! Check your inbox and click the link to set a new password.')
    } catch (e: any) {
      setAuthError(e.message || 'Could not send reset email. Please try again.')
    }
    setAuthLoading(false)
  }

  // ── Update password after reset redirect ──
  const handleResetPassword = async () => {
    if (!authPassword.trim() || authPassword.length < 8) {
      setAuthError('Password must be at least 8 characters.'); return
    }
    setAuthLoading(true); setAuthError('')
    try {
      const sb = await getSb()
      const { error } = await sb.auth.updateUser({ password: authPassword })
      if (error) throw error
      setShowAuthModal('none')
      setSubStatus('active')
      setShowPaywall(false)
      window.history.replaceState({}, '', '/dashboard')
    } catch (e: any) {
      setAuthError(e.message || 'Could not update password. Please try again.')
    }
    setAuthLoading(false)
  }

  // ── Handle auth (signup / login) ──
  const handleAuth = async (mode: 'signup' | 'login') => {
    if (!authEmail.trim() || !authPassword.trim()) {
      setAuthError('Please enter your email and password.')
      return
    }
    if (mode === 'signup' && authPassword.length < 8) {
      setAuthError('Password must be at least 8 characters.')
      return
    }
    setAuthLoading(true)
    setAuthError('')
    try {
      const sb = await getSb()
      if (mode === 'signup') {
        const { data, error } = await sb.auth.signUp({ email: authEmail.trim(), password: authPassword })
        if (error) throw error
        if (data.user) {
          setAuthUser(data.user)
          await saveToCloud(data.user)
          setShowAuthModal('none')
          // New user — start onboarding mission if not already complete
          if (!missionComplete) {
            setMissionPhase(1)
            setMissionStep(0)
            setMissionNavLocked(true)
            setActiveTab('home')
          }
        }
      } else {
        const { data, error } = await sb.auth.signInWithPassword({ email: authEmail.trim(), password: authPassword })
        if (error) throw error
        if (data.user) {
          setAuthUser(data.user)
          // Store this user's ID so we can detect device-sharing
          localStorage.setItem('aureus_last_user_id', data.user.id)
          const loaded = await loadFromCloud(data.user)
          setSubStatus('active')
          setShowPaywall(false)
          setShowAuthModal('none')
          if (!loaded || !missionComplete) {
            setMissionPhase(1); setMissionStep(0); setMissionNavLocked(true)
          }
        }
      }
    } catch (e: any) {
      setAuthError(e.message?.includes('Invalid login') ? 'Incorrect email or password.' : e.message || 'Something went wrong. Please try again.')
    }
    setAuthLoading(false)
  }

  // ── Check for existing Supabase session on mount ──
  useEffect(() => {
    const checkSession = async () => {
      // Handle password reset redirect
      if (window.location.search.includes('reset=true')) {
        setShowAuthModal('reset')
        setSubStatus('active')
        setShowPaywall(false)
        return
      }
      try {
        const sb = await getSb()
        const { data } = await sb.auth.getSession()
        if (data.session?.user) {
          setAuthUser(data.session.user)
          const currentUserId = data.session.user.id
          // If a different user was last logged in on this device, clear their local data
          const lastUserId = localStorage.getItem('aureus_last_user_id')
          if (lastUserId && lastUserId !== currentUserId) {
            localStorage.removeItem('aureus_data')
            localStorage.removeItem('aureus_business')
            localStorage.removeItem('aureus_user_token')
          }
          localStorage.setItem('aureus_last_user_id', currentUserId)
          const hasLocal = !!localStorage.getItem('aureus_data')
          if (!hasLocal) {
            const loaded = await loadFromCloud(data.session.user)
            if (loaded) {
              setSubStatus('active')
              setShowPaywall(false)
            } else {
              // New user with no data — set active and trigger onboarding
              setSubStatus('active')
              setShowPaywall(false)
              setMissionPhase(1)
              setMissionStep(0)
              setMissionNavLocked(true)
            }
          } else {
            // Always load from cloud to ensure we have the latest data for this user
            const loaded = await loadFromCloud(data.session.user)
            if (loaded) {
              setSubStatus('active')
              setShowPaywall(false)
            } else {
              // Cloud empty but has local — still set active, check if onboarding needed
              setSubStatus('active')
              setShowPaywall(false)
            }
          }
        }
      } catch {}
    }
    checkSession()
  }, [])

  // ── Auto-sync every 60 seconds when logged in ──
  useEffect(() => {
    if (!authUser || !onboardingComplete) return
    const timer = setInterval(() => saveToCloud(), 60000)
    return () => clearInterval(timer)
  }, [authUser, onboardingComplete, incomeStreams, expenses, debts, goals, wins])

  // ── Save to cloud when onboarding completes ──
  useEffect(() => {
    if (onboardingComplete && authUser) saveToCloud()
  }, [onboardingComplete])

  // ── Logout — clears local data and signs out of Supabase ──
  const handleLogout = async () => {
    try {
      // Save to cloud first so no data is lost
      if (authUser) await saveToCloud()
      // Sign out of Supabase
      const sb = await getSb()
      await sb.auth.signOut()
    } catch {}
    // Clear ALL local data so the next user starts fresh
    localStorage.removeItem('aureus_data')
    localStorage.removeItem('aureus_business')
    localStorage.removeItem('aureus_user_token')
    localStorage.removeItem('aureus_last_user_id')
    // Reload the page for a completely clean state
    window.location.reload()
  }

  // ── Open Stripe Customer Portal ──
  const openCustomerPortal = async () => {
    setPortalLoading(true)
    setPortalError('')
    try {
      const userToken = localStorage.getItem('aureus_user_token') || ''
      const email = authUser?.email || ''
      const res = await fetch('/api/create-portal-session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userToken, email })
      })
      const data = await res.json()
      if (data.url) {
        window.location.href = data.url
      } else {
        setPortalError(data.error || 'Could not open billing portal. Please contact support.')
      }
    } catch {
      setPortalError('Something went wrong. Please try again.')
    }
    setPortalLoading(false)
  }

  // ── Support AI chat handler ──
  const handleSupportMessage = async (message: string) => {
    setSupportLoading(true)
    try {
      const res = await fetch('/api/budget-coach', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          mode: 'question',
          question: `[AUREUS SUPPORT — APP HELP ONLY. Answer the support question below. You are a friendly app support agent, NOT a financial coach.]

APP STRUCTURE — be precise with these directions:
- TABS (top nav): Home, Aureus (chat), Change, Treasury, Roadmap, Wins, Quick View. Everything else is in the Quick Access grid on the Home tab.
- INCOME/EXPENSES/DEBTS/GOALS/ASSETS: Treasury tab
- CHANGE WORK: Change tab — Dickens Process, Values, Compelling Future, Money Mirror, Identity
- NOTIFICATIONS + DAILY EMAIL + PARTNER EMAIL + MEAL PLAN: Insights tab (in Quick Access on Home) → scroll down to the notification/email section
- NAME: Two places — (1) Home tab → gold card "Your setup isn't complete" → Resume setup → first screen asks for name. OR (2) Insights tab → scroll down to "Your Profile" section → type name in the YOUR NAME field. The name updates immediately, no save button needed.
- QUICK VIEW: Quick View tab (in top nav) — shows money left, bills due, budget vs actual
- BUSINESS: Business tab (in Quick Access on Home)
- COACH CHAT: Aureus tab
- SUPPORT: tap the ? button top right
- SIGN OUT: scroll to very bottom of any page → "Sign out (email)" link
- LEGAL PAGES: scroll to very bottom → Terms, Privacy Policy etc links
- SUBSCRIPTION/CANCEL: scroll to very bottom → "Manage subscription / Cancel"

User question: "${message}"

Answer in 2-4 sentences. Be specific about exactly which tab and where to scroll. If technical error, suggest refresh then email support@aureusplutus.app`,
          financialData: {}, memory: {}, countryConfig: currentCountryConfig
        })
      })
      const data = await res.json()
      setSupportMessages(prev => [...prev, { role: 'agent', content: data.message || data.advice || 'Try refreshing the app. If the issue persists, email support@aureusplutus.app and we\'ll sort it out.' }])
    } catch {
      setSupportMessages(prev => [...prev, { role: 'agent', content: "I'm having trouble connecting. Please email support@aureusplutus.app and we'll help you directly." }])
    }
    setSupportLoading(false)
    setTimeout(() => supportEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100)
  }

  // ── Business coach chat handler ──
  const handleBizChat = async (message: string) => {
    if (!message.trim()) return
    setBizChatMessages(prev => [...prev, { role: 'user', content: message }])
    setBizChatInput('')
    setBizChatLoading(true)
    try {
      const totalRevenue = businessRevenue.reduce((s: number, r: any) => s + parseFloat(r.amount || '0') * (r.frequency === 'weekly' ? 52 : r.frequency === 'fortnightly' ? 26 : 12) / 12, 0)
      const totalExpenses = businessExpenses.reduce((s: number, e: any) => s + parseFloat(e.amount || '0') * (e.frequency === 'weekly' ? 52 : e.frequency === 'fortnightly' ? 26 : 12) / 12, 0)
      const profit = totalRevenue - totalExpenses
      const margin = totalRevenue > 0 ? (profit / totalRevenue * 100) : 0
      const cacVal = parseFloat(bizLeads?.cac || '0')
      const ltvVal = parseFloat(bizLeads?.ltv || '0') || (parseFloat(bizLeads?.avgTransactionValue || '0') * parseFloat(bizLeads?.purchasesPerYear || '0') * parseFloat(bizLeads?.avgCustomerLifeYears || '0'))
      const ltvCacVal = cacVal > 0 && ltvVal > 0 ? ltvVal / cacVal : 0
      const offerScoreVal = Math.round(((bizOffer?.dreamOutcome ? 1 : 0) * 20) + (bizOffer?.likelihood / 10 * 20) + (bizOffer?.timeDelay / 10 * 20) + (bizOffer?.effort / 10 * 20) + (bizOffer?.guarantee ? 20 : 0))
      const res = await fetch('/api/budget-coach', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          mode: 'question',
          question: `[BUSINESS GROWTH COACH — HORMOZI FRAMEWORK]
You are a business growth coach who uses Alex Hormozi's frameworks from $100M Offers and $100M Leads.
NEVER advise on: business structure, tax deductions, GST, BAS, employment law, contracts, accounting methods, business loans.
For those topics: decline and refer to accountant, BAS agent, ato.gov.au, business.gov.au.
YOU DO help with: understanding metrics, offer strength, lead economics, LTV:CAC ratios, growth levers, pricing strategy, profit margins, and Hormozi frameworks.
Be direct, specific, and actionable. Use Hormozi's language where relevant.

Business: ${businessProfile.name || 'unnamed'} | ${businessProfile.type} | ${businessProfile.industry}
Monthly Revenue: $${totalRevenue.toFixed(0)} | Expenses: $${totalExpenses.toFixed(0)} | Profit: $${profit.toFixed(0)} | Margin: ${margin.toFixed(1)}%
Revenue streams: ${businessRevenue.map((r: any) => r.name + ' $' + r.amount + '/' + r.frequency).join(', ') || 'none'}
Expenses: ${businessExpenses.map((e: any) => e.name + ' $' + e.amount + '/' + e.frequency).join(', ') || 'none'}
CAC: $${bizLeads?.cac || 'not set'} | LTV: $${ltvVal > 0 ? ltvVal.toFixed(0) : 'not set'} | LTV:CAC: ${ltvCacVal > 0 ? ltvCacVal.toFixed(1) + 'x' : 'not set'}
Monthly leads: ${bizLeads?.monthlyLeads || 'not set'} | Lead sources: ${bizLeads?.leadSource?.join(', ') || 'not set'}
Conversion rate: ${bizOffer?.conversionRate || 'not set'}%
Offer score: ${offerScoreVal}/100 | Dream outcome: ${bizOffer?.dreamOutcome || 'not defined'}
Guarantee: ${bizOffer?.guarantee || 'none'} | Price: $${bizOffer?.price || 'not set'} | Competitors charge: $${bizOffer?.competitors || 'not set'}

User: "${message}"`,
          financialData: {}, memory: budgetMemory, countryConfig: currentCountryConfig
        })
      })
      const data = await res.json()
      setBizChatMessages(prev => [...prev, { role: 'assistant', content: data.message || data.advice || "I can help you understand your business numbers." }])
    } catch { setBizChatMessages(prev => [...prev, { role: 'assistant', content: "Having trouble connecting. Try again shortly." }]) }
    setBizChatLoading(false)
    setTimeout(() => bizChatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100)
  }

  // ── Check subscription status on load ──
  useEffect(() => {
    const checkSub = async () => {
      // If returning from Stripe checkout success — skip Supabase check (handled by other effect)
      if (window.location.search.includes('checkout=success')) {
        return
      }
      let userToken = localStorage.getItem('aureus_user_token')
      if (!userToken) {
        userToken = 'aureus_' + Math.random().toString(36).slice(2) + Date.now().toString(36)
        localStorage.setItem('aureus_user_token', userToken)
      }
      try {
        const { createClient } = await import('@supabase/supabase-js')
        const supabaseUrl = (globalThis as any).__SUPABASE_URL__ || ''
        const supabaseKey = (globalThis as any).__SUPABASE_KEY__ || ''
        if (supabaseUrl && supabaseKey) {
          const sb = createClient(supabaseUrl, supabaseKey)
          const { data } = await sb.from('subscriptions').select('*').eq('user_token', userToken).single()
          if (data && (data.status === 'active' || data.status === 'trialing')) {
            setSubStatus(data.status)
            return
          }
        }
      } catch {}
      setSubStatus('cancelled')
      setShowPaywall(true)
    }
    checkSub()
  }, [])
