  // ── Chat message markdown renderer ──
  const renderChatMessage = (content: string, isUser: boolean) => {
    if (isUser) return <span>{content}</span>
    const lines = content.split('\n')
    return (
      <>
        {lines.map((line, i) => {
          const withLinks = line.replace(
            /\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,
            (_: string, text: string, url: string) => `<a href="${url}" target="_blank" rel="noopener noreferrer" style="color:${theme.accent};text-decoration:underline;font-weight:600;">${text}</a>`
          )
          const withBold = withLinks.replace(/\*\*(.*?)\*\*/g, '<strong style="font-weight:700;">$1</strong>')
          if (line.startsWith('• ') || line.startsWith('- ')) {
            return (
              <div key={i} style={{ display: 'flex', gap: '8px', marginBottom: '2px' }}>
                <span style={{ color: theme.accent, flexShrink: 0, marginTop: '1px' }}>•</span>
                <span dangerouslySetInnerHTML={{ __html: withBold.replace(/^[•\-]\s/, '') }} />
              </div>
            )
          }
          if (line.trim() === '') return <div key={i} style={{ height: '6px' }} />
          return <div key={i} dangerouslySetInnerHTML={{ __html: withBold }} style={{ marginBottom: '1px' }} />
        })}
      </>
    )
  }

  const generateMealPlan = async () => {
    setGeneratingMealPlan(true)
    setMealPlanError(null)
    try {
      const weeklyBudget = mealPlanPrefs.budget || (monthlySurplus > 0 ? Math.round(monthlySurplus * 0.25).toString() : '150')

      const response = await fetch('/api/meal-plan', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          people: mealPlanPrefs.people,
          budget: weeklyBudget,
          dietaryNeeds: mealPlanPrefs.dietaryNeeds,
          dislikes: mealPlanPrefs.dislikes,
          useDetailedPricing: mealPlanPrefs.useWebSearch,
          meals: mealPlanPrefs.meals || ['breakfast', 'lunch', 'dinner'],
          catalogText: catalogText || ''
        })
      })

      if (!response.ok) {
        const err = await response.json().catch(() => ({}))
        throw new Error((err as any)?.error || `Server error ${response.status}`)
      }

      const data = await response.json()
      const text: string = data.text || ''
      if (!text || text.trim().length < 100) throw new Error('No response — please try again.')

      const plan = {
        rawText: text,
        generatedAt: new Date().toISOString(),
        prefs: { ...mealPlanPrefs },
        weeklyBudget,
        usedCatalog: !!catalogText
      }
      setCurrentMealPlan(plan)
      setMealPlanHistory((prev: any[]) => [plan, ...prev.slice(0, 9)])
    } catch (e: any) {
      console.error('Meal plan error:', e)
      setMealPlanError(e?.message || 'Something went wrong. Please try again.')
    }
    setGeneratingMealPlan(false)
  }

