  const calculatePersonality = () => {
    const counts: {[key: string]: number} = {}
    Object.values(personalityAnswers).forEach(type => { counts[type] = (counts[type] || 0) + 1 })
    return Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || 'planner'
  }

